mapper.select:
select b.* from
(
select case_num,max(create_time) as create_time
from b_call_record a
where case_num in

    #{custNum}

and cid = #{cid}
group by case_num
) as a
left join b_call_record b on a.case_num = b.case_num and a.create_time = b.create_time

select count(distinct a.case_num)
from b_call_record as a
left join b_xiecheng_data as b on a.case_num = b.sha256_tel
where  a.create_time >=#{requestData} and a.create_time < #{endData} 
and  b.create_time >=#{requestData} and b.create_time < #{endData} 
and b.push_status = 2 and b.status = 1

    and b.api_code = #{apiCode}
    and a.api_code = #{apiCode}


    and (a.line_name not like CONCAT('%',#{lineName},'%') or a.line_name is null)

select count(distinct a.case_num)
from b_call_record as a
left join b_xiecheng_data as b on a.case_num = b.sha256_tel
left join b_marketing_transfer_sync_#{cid} as c on b.sha256_tel = c.cust_num
where  a.create_time >=#{requestData} and a.create_time < #{endData} 
  and  b.create_time >=#{requestData} and b.create_time < #{endData} 
  and b.push_status = 2 and b.status = 1
  and c.request_data = #{requestData}

    and c.reserve_field1 -> '$.convType'=#{convType}


    and (a.line_name not like CONCAT('%',#{lineName},'%') or a.line_name is null)


    and c.api_code = #{apiCode}
    and b.api_code = #{apiCode}
    and a.api_code = #{apiCode}

select case_num as caseNum, call_start_time as callStartTime from b_call_record where call_status='12' and case_num in
#{key}
and call_start_time >= '${bizDate} 00:00:00' and call_start_time <= '${bizDate} 23:59:59' group by case_num having count(*)>0

select case_num from b_call_record where call_status='12' and case_num in
#{key}
and date(create_time) = #{nowDate} group by case_num

SELECT min(bcr.id)
FROM b_call_record bcr
         LEFT JOIN b_call_record_log bcrl
                   ON bcr.id = bcrl.record_id
WHERE bcr.api_code = #{apiCode,jdbcType=VARCHAR}
  and bcr.create_time >= #{date}
  AND bcrl.record_id IS NULL;

SELECT bcr.*
FROM b_call_record bcr
    LEFT JOIN b_call_record_log bcrl
        ON bcr.id = bcrl.record_id
WHERE bcr.api_code = #{apiCode,jdbcType=VARCHAR}
  AND bcr.create_time >= #{date}

    and bcr.id > #{minId,jdbcType=BIGINT}

  AND bcrl.record_id IS NULL
ORDER BY bcr.id
LIMIT #{limit,jdbcType=INTEGER}

mapper.update:
update b_call_record
set sync_status=#{syncStatus}
where id in

    #{id}

update b_call_record
set sync_status = #{syncStatus}
where id = #{id}

mapper.select:
select task_name from b_call_record
where api_code = #{apiCode}
and case_num = #{userKey}
and create_time between #{startDate} and #{endDate}
order by create_time desc
limit 1

select b.case_num as caseNum, b.task_name as taskName
from (
    select case_num, max(create_time) as create_time
    from b_call_record
    where api_code = #{apiCode}
    and case_num in

        #{userKey}

    and create_time between #{startDate} and #{endDate}
    group by case_num
) as a
left join b_call_record b on a.case_num = b.case_num and a.create_time = b.create_time
where b.task_name is not null
